// Captura as variáveis do payload
var temp = msg.payload.temperatura || 0;
var umidade = msg.payload.umidade || 0;
var co2 = msg.payload.co2 || 0;
var salaTag = (msg.payload.sala || "Sala_101").replace(" ", "_");

// Credenciais sem espaços e limpas
var botToken = "8463809598:AAHQIV9G5FfDuvIGo2ghqwmBigYQsnGVN3I";
var chatId = 8806880654;

// 1. Saída InfluxDB (Line Protocol)
var msgInflux = {
    headers: {
        "Authorization": "Token JN13TvalwfVdMN_VQsTVSiCgNXEuNnyaaGOluWo6rbFx3GpYjRnxpdWFa8pZHVpjt_0aUMoMqVEgRfimylmSww==",
        "Content-Type": "text/plain; charset=utf-8"
    },
    payload: 'qualidade_ar,sala=' + salaTag + ' temperatura=' + parseFloat(temp) + ',umidade=' + parseFloat(umidade) + ',co2=' + parseInt(co2)
};

// 2. Saída Debug
var msgDebug = {
    payload: { sala: salaTag, temperatura: temp, umidade: umidade, co2: co2 }
};

// 3. Saída Atuador MQTT (ESP32)
var statusAlerta = "NORMAL";
// NOVA LÓGICA: Dispara crítico se CO2 > 2000 OU Temperatura >= 50
if (co2 > 2000 || temp >= 45) {
    statusAlerta = "CRITICO";
} else if (co2 > 1000 || temp > 30) {
    statusAlerta = "ATENCAO";
}

var msgAtuador = { payload: statusAlerta };

// 4. Saída API Telegram
var msgTelegram = null;

if (statusAlerta === "CRITICO") {
    // Trocamos os *asteriscos* por <b> para usar HTML e não dar erro com o underline
    var textoMensagem = "🚨 <b>ALERTA AMBIENTAL - MACKENZIE</b>\n" +
        "🎯 <b>ODS 3 - Meta 3.9 (Saúde e Bem-Estar)</b>\n\n" +
        "📍 <b>Ambiente:</b> " + salaTag.replace("_", " ") + "\n" +
        "⚠️ <b>Status:</b> CRÍTICO\n" +
        "💨 <b>CO2:</b> " + co2 + " PPM\n" +
        "🌡️ <b>Temperatura:</b> " + temp + "°C\n" +
        "💧 <b>Umidade:</b> " + umidade + "%\n\n" +
        "⚙️ <b>Ação:</b> Exaustores e atuadores de emergência acionados via IoT.";

    msgTelegram = {
        url: "https://api.telegram.org/bot" + botToken + "/sendMessage",
        headers: {
            "Content-Type": "application/json"
        },
        payload: {
            chat_id: chatId,
            text: textoMensagem,
            parse_mode: "HTML" // Mudamos para HTML para evitar conflitos
        }
    };
}

// Retorna as 4 saídas
return [msgInflux, msgDebug, msgAtuador, msgTelegram];

